window.PAGES = window.PAGES || {};
window.PAGES["day6-theory"] = {"title": "OCI Security, Encryption, PKI & Vault/KMS \u2014 Day 6 | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 6 \u2014 ADDITIONAL WIDGET STYLES\n   (encryption simulator, PKI chain, TLS handshake, vault\n   console, key/secret lifecycle, bastion, audit timeline,\n   attack simulation, architecture design exercise)\n   ============================================================ */\n\n/* --- encryption simulator --- */\n.enc-flow{display:flex; align-items:center; gap:14px; flex-wrap:wrap; justify-content:center; margin:16px 0;}\n.enc-box{flex:1; min-width:160px; background:var(--panel); border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:14px; text-align:center;}\n.enc-box .label{font-size:10px; text-transform:uppercase; color:var(--text-3); letter-spacing:.06em; margin-bottom:6px;}\n.enc-box .content{font-family:var(--font-mono); font-size:13px; word-break:break-all; min-height:20px;}\n.enc-arrow{font-size:20px; color:var(--red-bright); flex-shrink:0;}\n.key-icon{font-size:22px;}\n\n/* --- PKI chain --- */\n.pki-chain{display:flex; flex-direction:column; align-items:center; gap:4px;}\n.pki-node{width:100%; max-width:420px; border:1px solid var(--border-strong); border-radius:10px; padding:14px; text-align:center; font-size:13px; cursor:pointer; transition:.2s; background:var(--panel);}\n.pki-node:hover, .pki-node.active{border-color:var(--red); background:var(--red-dim);}\n.pki-node.root{border-color:var(--amber);}\n.pki-arrow-down{color:var(--text-3);}\n.pki-detail{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; margin-top:12px; font-size:13px; color:var(--text-2); min-height:50px;}\n\n/* --- vault console dashboard --- */\n.vault-stats{display:grid; grid-template-columns:repeat(4,1fr); gap:12px;}\n@media (max-width:800px){.vault-stats{grid-template-columns:1fr 1fr;}}\n.vault-stat{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; text-align:center;}\n.vault-stat .v{font-family:var(--font-display); font-size:22px;}\n.vault-stat .l{font-size:10px; text-transform:uppercase; color:var(--text-3); letter-spacing:.06em; margin-top:4px;}\n.key-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; margin-bottom:8px;}\n.key-card-top{display:flex; justify-content:space-between; align-items:center;}\n.key-actions{display:flex; gap:6px; flex-wrap:wrap; margin-top:8px;}\n.key-state{font-size:10px; padding:2px 10px; border-radius:20px;}\n.key-state.enabled{background:var(--green-dim); color:var(--green);}\n.key-state.disabled{background:var(--amber-dim); color:var(--amber);}\n.key-state.pending-deletion{background:var(--red-dim); color:var(--red-bright);}\n\n/* --- rotation timeline --- */\n.rotation-timeline{display:flex; align-items:center; gap:6px; overflow-x:auto; padding:10px 0; flex-wrap:wrap;}\n.rot-step{flex-shrink:0; min-width:110px; text-align:center; padding:12px 8px; border-radius:8px; background:var(--panel); border:1px solid var(--border); font-size:11.5px;}\n.rot-step.current{border-color:var(--red-bright); background:var(--red-dim); color:var(--red-bright);}\n.rot-arrow{color:var(--text-3);}\n\n/* --- secret version history --- */\n.version-row{display:flex; justify-content:space-between; align-items:center; padding:10px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:6px; font-size:13px;}\n.version-row.current{border-color:var(--green); background:var(--green-dim);}\n\n/* --- DR / replication --- */\n.dr-regions{display:flex; align-items:center; justify-content:center; gap:40px; margin:20px 0;}\n.dr-region{width:150px; text-align:center; padding:16px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.dr-region.primary{border-color:var(--blue);}\n.dr-region.secondary{border-color:var(--green);}\n.dr-region.failed{opacity:.35; filter:grayscale(1);}\n.dr-arrow{font-size:22px; color:var(--text-3);}\n\n/* --- bastion --- */\n.bastion-flow{display:flex; align-items:center; gap:6px; overflow-x:auto; flex-wrap:wrap; padding:10px 0;}\n\n/* --- audit timeline --- */\n.audit-item{display:flex; gap:12px; padding:10px 0; border-bottom:1px solid var(--border); font-size:12.5px;}\n.audit-item .audit-time{color:var(--text-3); font-family:var(--font-mono); width:130px; flex-shrink:0;}\n.audit-item .audit-icon{width:20px; flex-shrink:0;}\n\n/* --- attack simulation --- */\n.mistake-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; cursor:pointer; transition:.2s;}\n.mistake-card:hover{border-color:var(--red);}\n.attack-result{margin-top:12px; padding:12px 14px; border-radius:8px; font-size:13px; display:none; background:var(--red-dim); color:var(--red-bright); border:1px solid rgba(199,70,52,.35);}\n\n/* --- architecture design exercise --- */\n.design-grid{display:grid; grid-template-columns:1fr 1fr; gap:16px;}\n@media (max-width:800px){.design-grid{grid-template-columns:1fr;}}\n.design-score-ring{width:110px; height:110px; border-radius:50%; position:relative; background:conic-gradient(var(--green) calc(var(--dscore,0)*3.6deg), var(--panel-2) 0); transition:background .6s ease;}\n.design-score-ring::before{content:\"\"; position:absolute; inset:8px; border-radius:50%; background:var(--panel);}\n.design-score-ring span{position:relative; display:flex; align-items:center; justify-content:center; height:100%; font-family:var(--font-display); font-size:22px; font-weight:700;}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Security, Encryption, PKI &amp; Vault/KMS \u00b7 Day 6</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search encryption, PKI, vault, secrets\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Quiz score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1 \u00b7 Encryption Fundamentals</div>\n      <a class=\"nav-link\" href=\"#sec-encbasics\"><span class=\"num\">01</span>Encryption Fundamentals</a>\n      <a class=\"nav-link\" href=\"#sec-symmetric\"><span class=\"num\">02</span>Symmetric Encryption</a>\n      <a class=\"nav-link\" href=\"#sec-asymmetric\"><span class=\"num\">03</span>Asymmetric Encryption</a>\n      <a class=\"nav-link\" href=\"#sec-symvsasym\"><span class=\"num\">04</span>Symmetric vs Asymmetric</a>\n      <a class=\"nav-link\" href=\"#sec-atrest\"><span class=\"num\">05</span>Encryption at Rest</a>\n      <a class=\"nav-link\" href=\"#sec-intransit\"><span class=\"num\">06</span>Encryption in Transit &amp; TLS</a>\n      <a class=\"nav-link\" href=\"#sec-hybrid\"><span class=\"num\">07</span>Hybrid Encryption</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 2 \u00b7 PKI</div>\n      <a class=\"nav-link\" href=\"#sec-pki\"><span class=\"num\">08</span>PKI &amp; Chain of Trust</a>\n      <a class=\"nav-link\" href=\"#sec-certviz\"><span class=\"num\">09</span>Certificate Visualizer</a>\n      <a class=\"nav-link\" href=\"#sec-certvalidation\"><span class=\"num\">10</span>Certificate Validation</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3 \u00b7 OCI Vault &amp; KMS</div>\n      <a class=\"nav-link\" href=\"#sec-vaultkms\"><span class=\"num\">11</span>Vault &amp; KMS Architecture</a>\n      <a class=\"nav-link\" href=\"#sec-hsm\"><span class=\"num\">12</span>HSM &amp; Key Protection Modes</a>\n      <a class=\"nav-link\" href=\"#sec-mek\"><span class=\"num\">13</span>Master Encryption Keys</a>\n      <a class=\"nav-link\" href=\"#sec-encstorage\"><span class=\"num\">14</span>Encrypt Storage</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 4 \u00b7 Secrets Management</div>\n      <a class=\"nav-link\" href=\"#sec-secretsdash\"><span class=\"num\">15</span>Secrets Dashboard</a>\n      <a class=\"nav-link\" href=\"#sec-secretversions\"><span class=\"num\">16</span>Secret Versions &amp; Rotation</a>\n      <a class=\"nav-link\" href=\"#sec-keyrotation\"><span class=\"num\">17</span>Key Rotation Timeline</a>\n      <a class=\"nav-link\" href=\"#sec-appintegration\"><span class=\"num\">18</span>Application Integration</a>\n      <a class=\"nav-link\" href=\"#sec-keyreplication\"><span class=\"num\">19</span>Key Replication &amp; DR</a>\n      <a class=\"nav-link\" href=\"#sec-appfailure\"><span class=\"num\">20</span>Application Failure Diagnosis</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 5 \u00b7 Security Practices</div>\n      <a class=\"nav-link\" href=\"#sec-bestpractices\"><span class=\"num\">21</span>Best Practices Checklist</a>\n      <a class=\"nav-link\" href=\"#sec-networksecurity\"><span class=\"num\">22</span>Network Security Layers</a>\n      <a class=\"nav-link\" href=\"#sec-bastion\"><span class=\"num\">23</span>Bastion Service</a>\n      <a class=\"nav-link\" href=\"#sec-auditcompliance\"><span class=\"num\">24</span>Audit &amp; Compliance</a>\n      <a class=\"nav-link\" href=\"#sec-mistakes\"><span class=\"num\">25</span>Common Mistakes &amp; Attacks</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 6 \u00b7 Hands-On Lab</div>\n      <a class=\"nav-link\" href=\"#sec-console6\"><span class=\"num\">26</span>Console Simulator &amp; KMS Dashboard</a>\n      <a class=\"nav-link\" href=\"#sec-cli6\"><span class=\"num\">27</span>CLI Terminal</a>\n      <a class=\"nav-link\" href=\"#sec-labs6\"><span class=\"num\">28</span>Hands-On Labs</a>\n      <a class=\"nav-link\" href=\"#sec-troubleshoot6\"><span class=\"num\">29</span>Troubleshooting Lab</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 7-9 \u00b7 Design &amp; Certification</div>\n      <a class=\"nav-link\" href=\"#sec-archdesign\"><span class=\"num\">30</span>Security Architecture Design</a>\n      <a class=\"nav-link\" href=\"#sec-cheatsheet6\"><span class=\"num\">31</span>Cheat Sheets</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards6\"><span class=\"num\">32</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-quiz6\"><span class=\"num\">33</span>Certification Quiz</a>\n      <a class=\"nav-link\" href=\"#sec-cert6\"><span class=\"num\">34</span>Certificate Preview</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Security &amp; Cryptography Track</span>\n      <h1>Day 6: Encrypt it,<br>protect it, <span class=\"accent\">prove it.</span></h1>\n      <p class=\"lede\">Encryption fundamentals, PKI, OCI Vault, KMS, HSM, secrets management, key rotation, and disaster recovery \u2014 operate a real enterprise security platform without an OCI account.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>34</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">20</b><span>Certification MCQs</span></div>\n        <div class=\"hstat\"><b>12</b><span>Live simulators</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-encbasics\" class=\"btn btn-primary\">Start learning \u2192</a>\n        <a href=\"#sec-quiz6\" class=\"btn btn-ghost\">Jump to certification quiz</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 ENCRYPTION FUNDAMENTALS -->\n<section class=\"chapter reveal\" id=\"sec-encbasics\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Encryption Fundamentals</h2>\n  <p class=\"dek\">Type a message and watch it become unreadable, then readable again \u2014 the core loop behind every security control in this module.</p>\n  <div class=\"panel\">\n    <input class=\"mini-input\" id=\"enc-plaintext\" value=\"Transfer $500 to account 8842\" style=\"width:100%; margin-bottom:14px;\">\n    <button class=\"chip-btn active\" id=\"enc-run\">Encrypt then decrypt</button>\n    <div class=\"enc-flow mt-lg\">\n      <div class=\"enc-box\"><div class=\"label\">Plaintext</div><div class=\"content\" id=\"enc-out-plain\">\u2014</div></div>\n      <div class=\"enc-arrow\">\ud83d\udd11\u2192</div>\n      <div class=\"enc-box\"><div class=\"label\">Ciphertext</div><div class=\"content\" id=\"enc-out-cipher\" style=\"color:var(--red-bright);\">\u2014</div></div>\n      <div class=\"enc-arrow\">\u2192\ud83d\udd11</div>\n      <div class=\"enc-box\"><div class=\"label\">Decrypted</div><div class=\"content\" id=\"enc-out-decrypted\" style=\"color:var(--green);\">\u2014</div></div>\n    </div>\n  </div>\n  <div class=\"grid grid-4 mt-lg\">\n    <div class=\"card\"><h4>Plaintext</h4><p>The original, readable data before any transformation.</p></div>\n    <div class=\"card\"><h4>Ciphertext</h4><p>The scrambled output \u2014 meaningless without the right key.</p></div>\n    <div class=\"card\"><h4>Key</h4><p>The secret input that controls the transformation \u2014 lose it, lose the data.</p></div>\n    <div class=\"card\"><h4>Algorithm</h4><p>The mathematical procedure (AES, RSA) that performs the transformation.</p></div>\n  </div>\n</section>\n\n<!-- 02 SYMMETRIC ENCRYPTION -->\n<section class=\"chapter reveal\" id=\"sec-symmetric\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Symmetric Encryption</h2>\n  <p class=\"dek\">One key both encrypts and decrypts \u2014 fast, but both parties must already share that same secret key.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>AES</h4><p>The modern standard \u2014 AES-256 is what OCI uses for encryption at rest.</p></div>\n    <div class=\"card\"><h4>DES</h4><p>Legacy 56-bit cipher, broken by brute force \u2014 historical interest only.</p></div>\n    <div class=\"card\"><h4>3DES</h4><p>Triple-applied DES, slow, being phased out industry-wide.</p></div>\n    <div class=\"card\"><h4>ChaCha20</h4><p>A fast modern stream cipher, popular in TLS on mobile/low-power devices.</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <button class=\"chip-btn active\" id=\"sym-run\">Encrypt a file with one shared key</button>\n    <div class=\"enc-flow mt-lg\">\n      <div class=\"enc-box\"><div class=\"key-icon\">\ud83d\udcc4</div>report.pdf</div>\n      <div class=\"enc-arrow\" id=\"sym-arrow1\">\ud83d\udd11\u2192</div>\n      <div class=\"enc-box\"><div class=\"key-icon\">\ud83d\udd12</div><span id=\"sym-cipher-label\">report.pdf.enc</span></div>\n    </div>\n    <p class=\"small center mt-lg\" id=\"sym-msg\">Same key is used by the sender to encrypt and the receiver to decrypt \u2014 key distribution is the hard part.</p>\n  </div>\n</section>\n\n<!-- 03 ASYMMETRIC ENCRYPTION -->\n<section class=\"chapter reveal\" id=\"sec-asymmetric\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Asymmetric Encryption</h2>\n  <p class=\"dek\">Two mathematically linked keys \u2014 a public key anyone can use to encrypt, and a private key only you hold to decrypt.</p>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>RSA</h4><p>Based on the difficulty of factoring large primes \u2014 widely used for key exchange and signatures.</p></div>\n    <div class=\"card\"><h4>ECC</h4><p>Elliptic Curve Cryptography \u2014 equivalent security to RSA with much smaller keys, faster.</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <button class=\"chip-btn active\" id=\"asym-run\">Encrypt with Public Key, decrypt with Private Key</button>\n    <div class=\"enc-flow mt-lg\">\n      <div class=\"enc-box\"><div class=\"key-icon\">\ud83d\udd13</div>Sender has: Public Key</div>\n      <div class=\"enc-arrow\">\u2192</div>\n      <div class=\"enc-box\"><div class=\"key-icon\">\ud83d\udd12</div><span id=\"asym-cipher-label\">Ciphertext</span></div>\n      <div class=\"enc-arrow\">\u2192</div>\n      <div class=\"enc-box\"><div class=\"key-icon\">\ud83d\udd11</div>Receiver has: Private Key</div>\n    </div>\n    <p class=\"small center mt-lg\" id=\"asym-msg\">Anyone can encrypt with the public key; only the private key holder can decrypt \u2014 no shared secret ever travels.</p>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>A digital signature reverses the direction: the sender signs with their <em>private</em> key, and anyone can verify with the sender's <em>public</em> key \u2014 proving authenticity, not confidentiality.</div></div>\n</section>\n\n<!-- 04 SYMMETRIC VS ASYMMETRIC -->\n<section class=\"chapter reveal\" id=\"sec-symvsasym\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Symmetric vs Asymmetric</h2>\n  <table class=\"cmp\">\n    <tr><th></th><th>Symmetric</th><th>Asymmetric</th></tr>\n    <tr><td>Keys</td><td>One shared secret key</td><td>A public/private key pair</td></tr>\n    <tr><td>Speed</td><td>Fast, low overhead</td><td>Much slower, computationally heavy</td></tr>\n    <tr><td>Key distribution</td><td>Hard \u2014 the key itself must be shared secretly</td><td>Easy \u2014 the public key can be shared openly</td></tr>\n    <tr><td>Scalability</td><td>Poor for many parties (n\u00b2 key pairs)</td><td>Scales well \u2014 everyone just needs the public key</td></tr>\n    <tr><td>Typical use</td><td>Bulk data encryption (AES-256 at rest)</td><td>Key exchange, digital signatures, certificates</td></tr>\n  </table>\n  <div class=\"panel mt-lg\">\n    <div class=\"dtree\">\n      <div class=\"dt-q\">You need to encrypt a 4GB database backup file as fast as possible. Which do you use?</div>\n      <div class=\"dt-opts\"><button class=\"chip-btn\" data-sa=\"asym\">Asymmetric</button><button class=\"chip-btn\" data-sa=\"sym\">Symmetric</button></div>\n      <div class=\"dt-result\" id=\"sa-result\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- 05 ENCRYPTION AT REST -->\n<section class=\"chapter reveal\" id=\"sec-atrest\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Encryption at Rest</h2>\n  <p class=\"dek\">Every OCI storage service is encrypted at rest by default, using AES-256.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>\ud83d\udcbd Block Volume</h4><p>Encrypted transparently before data ever touches disk.</p></div>\n    <div class=\"card\"><h4>\ud83d\udce6 Object Storage</h4><p>Every object encrypted server-side automatically.</p></div>\n    <div class=\"card\"><h4>\ud83d\uddc4 Database</h4><p>Transparent Data Encryption (TDE) protects data files at rest.</p></div>\n    <div class=\"card\"><h4>\ud83d\udcbe Boot Volume</h4><p>The OS disk itself is encrypted from first boot.</p></div>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>OCI encrypts everything at rest by default using Oracle-managed keys \u2014 using your own Vault key is optional, for when you need control over rotation, disablement, and audit of the encryption key itself.</div></div>\n</section>\n\n<!-- 06 ENCRYPTION IN TRANSIT & TLS -->\n<section class=\"chapter reveal\" id=\"sec-intransit\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Encryption in Transit &amp; the TLS Handshake</h2>\n  <p class=\"dek\">Data moving across a network is protected by TLS, which combines both encryption types you just learned.</p>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"tls6-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"tls6-play\">\u25b6 Animate handshake</button></div>\n    <p class=\"small center mt-lg\" id=\"tls6-msg\">Asymmetric crypto establishes trust and exchanges a session key; symmetric crypto (fast) encrypts the actual data.</p>\n  </div>\n</section>\n\n<!-- 07 HYBRID ENCRYPTION -->\n<section class=\"chapter reveal\" id=\"sec-hybrid\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">Encryption Fundamentals</span></div>\n  <h2>Hybrid Encryption</h2>\n  <p class=\"dek\">Real systems (including OCI Vault) combine both: asymmetric to protect a small key, symmetric to protect the actual data.</p>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"hybrid-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"hybrid-play\">\u25b6 Animate envelope encryption</button></div>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>This exact pattern is called <strong>envelope encryption</strong> \u2014 OCI Vault's Master Encryption Key never directly encrypts your data; it encrypts a Data Encryption Key, which does the bulk work.</div></div>\n</section>\n<!-- 08 PKI & CHAIN OF TRUST -->\n<section class=\"chapter reveal\" id=\"sec-pki\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">PKI</span></div>\n  <h2>PKI(Public Key Infrastructure) &amp; Chain of Trust</h2>\n  <p class=\"dek\">Click each level of the chain, top to bottom.</p>\n  <div class=\"pki-chain\" id=\"pki-chain\">\n    <div class=\"pki-node root\" data-pki=\"root\">\ud83c\udfdb Root CA (self-signed, offline)</div>\n    <div class=\"pki-arrow-down\">\u2193 signs</div>\n    <div class=\"pki-node\" data-pki=\"intermediate\">\ud83c\udfe2 Intermediate CA</div>\n    <div class=\"pki-arrow-down\">\u2193 signs</div>\n    <div class=\"pki-node\" data-pki=\"leaf\">\ud83c\udf10 Leaf Certificate (yourdomain.com)</div>\n  </div>\n  <div class=\"pki-detail\" id=\"pki-detail\">Click a level above, starting from the Root CA.</div>\n  <div class=\"callout callout-trap\"><div class=\"ic\">\u26a0\ufe0f</div><div><b>Common Trap</b>Browsers don't trust your leaf certificate directly \u2014 they trust the Root CA, and verify the signature chain down to your certificate. A missing intermediate certificate in your server config is one of the most common \"certificate not trusted\" errors, even with a perfectly valid leaf cert.</div></div>\n</section>\n\n<!-- 09 CERTIFICATE VISUALIZER -->\n<section class=\"chapter reveal\" id=\"sec-certviz\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">PKI</span></div>\n  <h2>Certificate Visualizer</h2>\n  <p class=\"dek\">Walk through generating a certificate from scratch.</p>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"certviz-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"certviz-play\">\u25b6 Generate certificate</button></div>\n    <div class=\"lw-boot-log\" id=\"certviz-log\" style=\"margin-top:14px;\"></div>\n  </div>\n</section>\n\n<!-- 10 CERTIFICATE VALIDATION -->\n<section class=\"chapter reveal\" id=\"sec-certvalidation\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">PKI</span></div>\n  <h2>Certificate Validation Troubleshooting</h2>\n  <p class=\"dek\">Pick a certificate problem and diagnose it.</p>\n  <div class=\"cost-filters\" id=\"cert-case-btns\">\n    <button class=\"chip-btn active\" data-certcase=\"expired\">Expired Certificate</button>\n    <button class=\"chip-btn\" data-certcase=\"revoked\">Revoked Certificate</button>\n    <button class=\"chip-btn\" data-certcase=\"selfsigned\">Self-Signed Certificate</button>\n    <button class=\"chip-btn\" data-certcase=\"wronghost\">Wrong Hostname</button>\n  </div>\n  <div class=\"panel\" id=\"cert-case-panel\"></div>\n</section>\n<!-- 11 VAULT & KMS ARCHITECTURE -->\n<section class=\"chapter reveal\" id=\"sec-vaultkms\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">OCI Vault &amp; KMS</span></div>\n  <h2>Vault &amp; KMS Architecture</h2>\n  <p class=\"dek\">OCI Vault is the managed service; KMS is the underlying key management engine behind it.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>Vault</h4><p>A logical container for your keys and secrets, backed by dedicated or shared HSM partitions.</p></div>\n    <div class=\"card\"><h4>Master Encryption Key (MEK)</h4><p>The root key you manage \u2014 never leaves the Vault/HSM in plaintext.</p></div>\n    <div class=\"card\"><h4>Data Encryption Key (DEK)</h4><p>A key generated per operation, encrypted (\"wrapped\") by the MEK \u2014 this is envelope encryption in practice.</p></div>\n    <div class=\"card\"><h4>Secrets</h4><p>Arbitrary sensitive values (passwords, tokens) stored and versioned inside the Vault, separate from keys.</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <div class=\"vault-stats\">\n      <div class=\"vault-stat\"><div class=\"v\" style=\"color:var(--green);\">Healthy</div><div class=\"l\">Vault Status</div></div>\n      <div class=\"vault-stat\"><div class=\"v\">4</div><div class=\"l\">Active Keys</div></div>\n      <div class=\"vault-stat\"><div class=\"v\">7</div><div class=\"l\">Active Secrets</div></div>\n      <div class=\"vault-stat\"><div class=\"v\">HSM</div><div class=\"l\">Protection Mode</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- 12 HSM & KEY PROTECTION MODES -->\n<section class=\"chapter reveal\" id=\"sec-hsm\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">OCI Vault &amp; KMS</span></div>\n  <h2>HSM &amp; Key Protection Modes</h2>\n  <p class=\"dek\">A Hardware Security Module is tamper-resistant hardware that generates and stores keys \u2014 they're designed so the key material can never be extracted, even by the operator.</p>\n  <table class=\"cmp\">\n    <tr><th>Mode</th><th>Where the key lives</th><th>Use when</th></tr>\n    <tr><td>Software Protected</td><td>Software, in a shared multi-tenant KMS</td><td>Lower cost, standard workloads</td></tr>\n    <tr><td>Virtual Private Vault</td><td>Dedicated partition on shared HSM hardware</td><td>Need isolation but not a fully dedicated HSM</td></tr>\n    <tr><td>HSM Protected</td><td>FIPS 140-2 Level 3 validated HSM</td><td>Strict compliance (PCI DSS, HIPAA) requiring hardware-backed keys</td></tr>\n  </table>\n  <div class=\"panel mt-lg\">\n    <div class=\"dtree\">\n      <div class=\"dt-q\">A healthcare company must prove keys are protected by FIPS 140-2 Level 3 hardware for a HIPAA audit. Which protection mode?</div>\n      <div class=\"dt-opts\"><button class=\"chip-btn\" data-hsmq=\"software\">Software Protected</button><button class=\"chip-btn\" data-hsmq=\"hsm\">HSM Protected</button></div>\n      <div class=\"dt-result\" id=\"hsmq-result\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- 13 MASTER ENCRYPTION KEYS -->\n<section class=\"chapter reveal\" id=\"sec-mek\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">OCI Vault &amp; KMS</span></div>\n  <h2>Master Encryption Keys</h2>\n  <p class=\"dek\">Create, rotate, disable, and schedule deletion of keys \u2014 exactly like the real Vault console.</p>\n  <div class=\"panel\">\n    <div class=\"console-toolbar\">\n      <input class=\"mini-input\" id=\"mek-new-name\" placeholder=\"key name\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"mek-create\">\uff0b Create Key</button>\n    </div>\n    <div id=\"mek-list\" class=\"mt-lg\"></div>\n  </div>\n  <div class=\"callout callout-warn\"><div class=\"ic\">\u26a0\ufe0f</div><div><b>Exam Warning</b>Scheduling a key for deletion starts a mandatory waiting period (7\u201330 days) before permanent deletion \u2014 this exists specifically so an accidental deletion can be cancelled before data becomes permanently unrecoverable.</div></div>\n</section>\n\n<!-- 14 ENCRYPT STORAGE -->\n<section class=\"chapter reveal\" id=\"sec-encstorage\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">OCI Vault &amp; KMS</span></div>\n  <h2>Encrypt Storage with Your Own Key</h2>\n  <p class=\"dek\">Swap a storage resource from an Oracle-managed key to your own Vault key.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\" id=\"encstorage-target-btns\">\n      <button class=\"chip-btn active\" data-est=\"block\">Block Volume</button>\n      <button class=\"chip-btn\" data-est=\"object\">Object Storage Bucket</button>\n      <button class=\"chip-btn\" data-est=\"boot\">Boot Volume</button>\n      <button class=\"chip-btn\" data-est=\"file\">File Storage</button>\n    </div>\n    <button class=\"chip-btn active mt-lg\" id=\"encstorage-apply\">Assign Vault Key \"prod-mek-01\"</button>\n    <p class=\"small mt-lg\" id=\"encstorage-result\"></p>\n  </div>\n</section>\n<!-- 15 SECRETS DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-secretsdash\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Secrets Management</span></div>\n  <h2>Secrets Management Dashboard</h2>\n  <p class=\"dek\">Passwords, API keys, tokens, certificates, and database credentials \u2014 all stored, versioned, and access-controlled centrally.</p>\n  <div class=\"panel\">\n    <div class=\"console-toolbar\">\n      <input class=\"mini-input\" id=\"secret-new-name\" placeholder=\"secret name, e.g. db-password\" style=\"flex:1;\">\n      <select class=\"mini-input\" id=\"secret-new-type\"><option>Password</option><option>API Key</option><option>Token</option><option>Certificate</option></select>\n      <button class=\"chip-btn active\" id=\"secret-create\">\uff0b Create Secret</button>\n    </div>\n    <div id=\"secret-list\" class=\"mt-lg\"></div>\n  </div>\n</section>\n\n<!-- 16 SECRET VERSIONS & ROTATION -->\n<section class=\"chapter reveal\" id=\"sec-secretversions\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Secrets Management</span></div>\n  <h2>Secret Versions &amp; Rotation</h2>\n  <p class=\"dek\">Rotating a secret creates a new version \u2014 old versions can stay valid briefly so in-flight processes don't break.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"secver-rotate\">\ud83d\udd04 Rotate db-password</button>\n    <div id=\"secver-list\" class=\"mt-lg\"></div>\n  </div>\n</section>\n\n<!-- 17 KEY ROTATION TIMELINE -->\n<section class=\"chapter reveal\" id=\"sec-keyrotation\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Secrets Management</span></div>\n  <h2>Key Rotation Timeline</h2>\n  <p class=\"dek\">Three rotation models, same underlying mechanism: a new key version is created, old data can still be decrypted by prior versions.</p>\n  <div class=\"grid grid-3\">\n    <div class=\"card\"><h4>Manual Rotation</h4><p>An admin explicitly triggers rotation, on demand.</p></div>\n    <div class=\"card\"><h4>Scheduled Rotation</h4><p>Rotates automatically on a fixed calendar interval (e.g. every 90 days).</p></div>\n    <div class=\"card\"><h4>Automatic Rotation</h4><p>Fully managed rotation, often tied to application-integrated secret rotation (e.g. database password + secret updated together).</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <div class=\"rotation-timeline\" id=\"rotation-timeline\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"rotation-play\">\u25b6 Animate a rotation cycle</button></div>\n  </div>\n</section>\n\n<!-- 18 APPLICATION INTEGRATION -->\n<section class=\"chapter reveal\" id=\"sec-appintegration\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Secrets Management</span></div>\n  <h2>Application Integration</h2>\n  <p class=\"dek\">An application retrieves a secret at runtime, authenticating itself first \u2014 never hardcoding the value.</p>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"appint-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"appint-play\">\u25b6 Simulate secret retrieval</button></div>\n    <div class=\"lw-boot-log\" id=\"appint-log\" style=\"margin-top:14px;\"></div>\n  </div>\n</section>\n\n<!-- 19 KEY REPLICATION & DR -->\n<section class=\"chapter reveal\" id=\"sec-keyreplication\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Secrets Management</span></div>\n  <h2>Key Replication &amp; Disaster Recovery</h2>\n  <p class=\"dek\">Replicate a Vault to a second region so encrypted data stays decryptable if the primary region is unavailable.</p>\n  <div class=\"panel\">\n    <div class=\"dr-regions\">\n      <div class=\"dr-region primary\" id=\"dr-primary\">\ud83c\udfe2<br>us-ashburn-1<br><span class=\"small\">Primary Vault</span></div>\n      <div class=\"dr-arrow\" id=\"dr-arrow\">\u21c4</div>\n      <div class=\"dr-region secondary\" id=\"dr-secondary\">\ud83c\udfe2<br>us-phoenix-1<br><span class=\"small\">Replica Vault</span></div>\n    </div>\n    <div class=\"center\"><button class=\"chip-btn active\" id=\"dr-failover\">\ud83d\udd25 Simulate primary region failure</button> <button class=\"chip-btn\" id=\"dr-reset\">\u21ba Reset</button></div>\n    <p class=\"small center mt-lg\" id=\"dr-msg\">Both regions healthy \u2014 keys are replicated and in sync.</p>\n  </div>\n</section>\n\n<!-- 20 APPLICATION FAILURE DIAGNOSIS -->\n<section class=\"chapter reveal\" id=\"sec-appfailure\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">20</span><span class=\"track\">Secrets Management</span></div>\n  <h2>Application Failure Diagnosis</h2>\n  <p class=\"dek\">You rotated the database secret. The application just started throwing authentication errors. Why?</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"appfail-rotate\">Rotate secret now</button>\n    <p class=\"mono mt-lg\" style=\"color:var(--red-bright); display:none;\" id=\"appfail-error\">ERROR: FATAL: password authentication failed for user \"app_user\"</p>\n    <div class=\"quiz-opts mt-lg\" id=\"appfail-opts\" style=\"display:none;\">\n      <label class=\"quiz-opt\"><input type=\"radio\" name=\"appfail\" value=\"wrong1\">The Vault is down.</label>\n      <label class=\"quiz-opt\"><input type=\"radio\" name=\"appfail\" value=\"right\">The application is still using a cached old version of the secret, or the database's actual password wasn't updated to match the new secret version.</label>\n      <label class=\"quiz-opt\"><input type=\"radio\" name=\"appfail\" value=\"wrong2\">The network has a routing issue.</label>\n    </div>\n    <button class=\"chip-btn mt-lg\" id=\"appfail-check\" style=\"display:none;\">Check diagnosis</button>\n    <p class=\"small mt-lg\" id=\"appfail-feedback\"></p>\n  </div>\n</section>\n<!-- 21 BEST PRACTICES CHECKLIST -->\n<section class=\"chapter reveal\" id=\"sec-bestpractices\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">21</span><span class=\"track\">Security Practices</span></div>\n  <h2>Security Best Practices Checklist</h2>\n  <p class=\"dek\">Check off each practice as you review it.</p>\n  <div id=\"bp-list\"></div>\n</section>\n\n<!-- 22 NETWORK SECURITY LAYERS -->\n<section class=\"chapter reveal\" id=\"sec-networksecurity\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">22</span><span class=\"track\">Security Practices</span></div>\n  <h2>Network Security Layers</h2>\n  <p class=\"dek\">Security Lists, NSGs, Bastion, private access, and encryption work together as layered controls.</p>\n  <div class=\"castle-wrap\" id=\"netlayers\"></div>\n</section>\n\n<!-- 23 BASTION SERVICE -->\n<section class=\"chapter reveal\" id=\"sec-bastion\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">23</span><span class=\"track\">Security Practices</span></div>\n  <h2>Bastion Service</h2>\n  <p class=\"dek\">Bastion gives short-lived, brokered SSH access to private instances \u2014 no permanent jump box, no exposed public IP on the target.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"bastion-create\">Create Bastion Session (5 min TTL)</button>\n    <div class=\"bastion-flow mt-lg\" id=\"bastion-flow\"></div>\n    <p class=\"small mt-lg\" id=\"bastion-msg\">Create a session to establish a temporary SSH tunnel to a private instance.</p>\n  </div>\n</section>\n\n<!-- 24 AUDIT & COMPLIANCE -->\n<section class=\"chapter reveal\" id=\"sec-auditcompliance\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">24</span><span class=\"track\">Security Practices</span></div>\n  <h2>Audit &amp; Compliance</h2>\n  <h3>Audit event timeline</h3>\n  <div class=\"panel\">\n    <div id=\"audit-timeline\"></div>\n  </div>\n  <h3>Compliance frameworks</h3>\n  <div class=\"compliance-grid mt-lg\" id=\"compliance-grid6\">\n    <div class=\"compliance-card\" data-c6=\"pci\">PCI DSS</div>\n    <div class=\"compliance-card\" data-c6=\"hipaa\">HIPAA</div>\n    <div class=\"compliance-card\" data-c6=\"iso\">ISO 27001</div>\n    <div class=\"compliance-card\" data-c6=\"soc2\">SOC 2</div>\n    <div class=\"compliance-card\" data-c6=\"gdpr\">GDPR</div>\n    <div class=\"compliance-card\" data-c6=\"nist\">NIST</div>\n  </div>\n  <div class=\"cia-detail mt-lg\" id=\"compliance6-detail\">Click a framework above.</div>\n</section>\n\n<!-- 25 COMMON MISTAKES & ATTACKS -->\n<section class=\"chapter reveal\" id=\"sec-mistakes\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">25</span><span class=\"track\">Security Practices</span></div>\n  <h2>Common Security Mistakes</h2>\n  <p class=\"dek\">Click a mistake to see what an attacker does with it.</p>\n  <div class=\"grid grid-3\" id=\"mistake-grid\">\n    <div class=\"mistake-card\" data-m=\"hardcoded\">\ud83d\udd13 Hardcoded Secrets in Code</div>\n    <div class=\"mistake-card\" data-m=\"shared\">\ud83d\udc65 Shared Keys Across Teams</div>\n    <div class=\"mistake-card\" data-m=\"norotation\">\ud83d\udd01 No Key Rotation</div>\n    <div class=\"mistake-card\" data-m=\"excessive\">\ud83d\udee1 Excessive Permissions</div>\n    <div class=\"mistake-card\" data-m=\"publicbucket\">\ud83d\udce6 Public Buckets</div>\n    <div class=\"mistake-card\" data-m=\"noaudit\">\ud83d\udccb No Audit Logging</div>\n  </div>\n  <div class=\"attack-result\" id=\"mistake-result\"></div>\n</section>\n<!-- 26 CONSOLE SIMULATOR & KMS DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-console6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">26</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>OCI Console Simulator &amp; KMS Dashboard</h2>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/security</span></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\">\n        <div class=\"active\" data-panel6=\"vaults6\">\ud83d\udd10 Vaults</div>\n        <div data-panel6=\"keys6\">\ud83d\udd11 Keys</div>\n        <div data-panel6=\"secrets6\">\ud83d\udddd Secrets</div>\n        <div data-panel6=\"bastion6\">\ud83d\udda5 Bastion</div>\n      </div>\n      <div class=\"console-main\">\n        <div class=\"console-panel6\" id=\"panel6-vaults6\">\n          <table class=\"console-table\"><thead><tr><th>Vault</th><th>Type</th><th>Status</th></tr></thead>\n          <tbody><tr><td>prod-vault</td><td>Virtual Private Vault</td><td><span class=\"status-pill active\">Active</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel6\" id=\"panel6-keys6\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Key</th><th>Algorithm</th><th>Protection</th><th>State</th></tr></thead>\n          <tbody><tr><td>prod-mek-01</td><td>AES-256</td><td>HSM</td><td><span class=\"status-pill active\">Enabled</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel6\" id=\"panel6-secrets6\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Secret</th><th>Type</th><th>Version</th></tr></thead>\n          <tbody><tr><td>db-password</td><td>Password</td><td>3</td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel6\" id=\"panel6-bastion6\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Session</th><th>Target</th><th>TTL</th></tr></thead>\n          <tbody><tr><td>session-a1b2</td><td>db-vm-01 (private)</td><td>4m 12s remaining</td></tr></tbody></table>\n        </div>\n      </div>\n    </div>\n  </div>\n  <h3>KMS dashboard</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"vault-stats\">\n      <div class=\"vault-stat\"><div class=\"v\" style=\"color:var(--green);\">Healthy</div><div class=\"l\">Vault Health</div></div>\n      <div class=\"vault-stat\"><div class=\"v\" style=\"color:var(--green);\">4 Enabled</div><div class=\"l\">Key Status</div></div>\n      <div class=\"vault-stat\"><div class=\"v\">7 Active</div><div class=\"l\">Secret Status</div></div>\n      <div class=\"vault-stat\"><div class=\"v\" style=\"color:var(--blue);\">In Sync</div><div class=\"l\">Replication Status</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- 27 CLI TERMINAL -->\n<section class=\"chapter reveal\" id=\"sec-cli6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">27</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>CLI Terminal</h2>\n  <div class=\"terminal\">\n    <div class=\"terminal-tb\">oci-cli \u2014 vault &amp; kms \u2014 simulator</div>\n    <div id=\"term-out6\"></div>\n    <div class=\"term-input-row\"><span>$</span><input id=\"term-input6\" type=\"text\" placeholder=\"type: help\" autocomplete=\"off\"></div>\n  </div>\n  <p class=\"small mt-lg\">Try: <span class=\"mono\">help, oci kms management vault create, oci kms management key create, oci kms management key list, oci vault secret create, oci vault secret list, oci vault secret update, oci kms management key schedule-deletion, oci kms management key cancel-deletion, clear</span></p>\n</section>\n\n<!-- 28 HANDS-ON LABS -->\n<section class=\"chapter reveal\" id=\"sec-labs6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">28</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Hands-On Labs</h2>\n  <p class=\"dek\">Check off each lab as you complete the matching section above.</p>\n  <div id=\"labs6-list\"></div>\n  <p class=\"small center mt-lg\" id=\"labs6-progress\">0 / 9 labs complete</p>\n</section>\n\n<!-- 29 TROUBLESHOOTING LAB -->\n<section class=\"chapter reveal\" id=\"sec-troubleshoot6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">29</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Troubleshooting Lab</h2>\n  <div class=\"cost-filters\" id=\"ts6-case-btns\">\n    <button class=\"chip-btn active\" data-case6=\"accessdenied\">Access Denied</button>\n    <button class=\"chip-btn\" data-case6=\"expiredsecret\">Expired Secret</button>\n    <button class=\"chip-btn\" data-case6=\"wrongpolicy\">Wrong IAM Policy</button>\n    <button class=\"chip-btn\" data-case6=\"keydisabled\">Key Disabled</button>\n    <button class=\"chip-btn\" data-case6=\"scheduleddeletion\">Key Scheduled for Deletion</button>\n    <button class=\"chip-btn\" data-case6=\"replicationdelay\">Replication Delay</button>\n    <button class=\"chip-btn\" data-case6=\"appauthfail\">Application Auth Failure</button>\n  </div>\n  <div class=\"panel\" id=\"ts6-panel\"></div>\n</section>\n\n<!-- 30 SECURITY ARCHITECTURE DESIGN -->\n<section class=\"chapter reveal\" id=\"sec-archdesign\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">30</span><span class=\"track\">Design &amp; Certification</span></div>\n  <h2>Security Architecture Design Exercise</h2>\n  <p class=\"dek\">Design a highly secure OCI environment for a healthcare workload. Your choices are scored below.</p>\n  <div class=\"design-grid\">\n    <div class=\"panel\">\n      <div class=\"field-row\"><label>Vault type</label><select class=\"mini-input\" id=\"design-vault\" style=\"width:100%;\"><option value=\"shared\">Shared Vault</option><option value=\"vpv\">Virtual Private Vault</option></select></div>\n      <div class=\"field-row\"><label>Key protection mode</label><select class=\"mini-input\" id=\"design-keyprotect\" style=\"width:100%;\"><option value=\"software\">Software Protected</option><option value=\"hsm\">HSM Protected</option></select></div>\n      <div class=\"field-row\"><label>Admin access to private instances</label><select class=\"mini-input\" id=\"design-bastion\" style=\"width:100%;\"><option value=\"publicssh\">Direct public SSH</option><option value=\"bastion\">OCI Bastion (brokered, TTL-limited)</option></select></div>\n      <div class=\"field-row\"><label>Network security</label><select class=\"mini-input\" id=\"design-netsec\" style=\"width:100%;\"><option value=\"sl\">Security Lists only</option><option value=\"both\">Security Lists + NSGs</option></select></div>\n      <div class=\"field-row\"><label>IAM policy scope</label><select class=\"mini-input\" id=\"design-iam\" style=\"width:100%;\"><option value=\"broad\">Broad \"manage all-resources\" policy</option><option value=\"least\">Least-privilege, scoped policies</option></select></div>\n      <button class=\"chip-btn active\" id=\"design-evaluate\">Evaluate my design</button>\n    </div>\n    <div class=\"panel center\">\n      <div class=\"design-score-ring\" id=\"design-ring\" style=\"--dscore:0; margin:0 auto;\"><span id=\"design-score-val\">0</span></div>\n      <p class=\"small mt-lg\" id=\"design-feedback\">Make your selections and evaluate.</p>\n    </div>\n  </div>\n</section>\n<!-- 31 CHEAT SHEETS -->\n<section class=\"chapter reveal\" id=\"sec-cheatsheet6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">31</span><span class=\"track\">Certification Center</span></div>\n  <h2>Cheat Sheets</h2>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>Encryption</h4><ul style=\"margin-left:16px;\"><li>Symmetric = 1 key, fast, hard to distribute</li><li>Asymmetric = key pair, slow, easy to distribute</li><li>Envelope encryption = MEK wraps a DEK, DEK encrypts data</li></ul></div>\n    <div class=\"card\"><h4>PKI</h4><ul style=\"margin-left:16px;\"><li>Root CA \u2192 Intermediate CA \u2192 Leaf certificate</li><li>Browsers trust the Root, not the leaf directly</li><li>Missing intermediate = common \"untrusted\" error</li></ul></div>\n    <div class=\"card\"><h4>Vault &amp; KMS</h4><ul style=\"margin-left:16px;\"><li>Software / VPV / HSM protection modes</li><li>Scheduled deletion has a 7-30 day mandatory wait</li><li>HSM = FIPS 140-2 Level 3 tamper-resistant hardware</li></ul></div>\n    <div class=\"card\"><h4>Secrets</h4><ul style=\"margin-left:16px;\"><li>Rotation creates a new version, doesn't destroy old ones immediately</li><li>Never hardcode \u2014 retrieve at runtime with an authenticated principal</li><li>Cross-region replication protects against regional failure</li></ul></div>\n  </div>\n  <table class=\"cmp mt-lg\"><tr><th>CLI Reference</th></tr>\n    <tr><td class=\"mono\">oci kms management vault create</td></tr><tr><td class=\"mono\">oci kms management key create</td></tr>\n    <tr><td class=\"mono\">oci kms management key list</td></tr><tr><td class=\"mono\">oci vault secret create</td></tr>\n    <tr><td class=\"mono\">oci vault secret list</td></tr><tr><td class=\"mono\">oci vault secret update</td></tr>\n    <tr><td class=\"mono\">oci kms management key schedule-deletion</td></tr><tr><td class=\"mono\">oci kms management key cancel-deletion</td></tr></table>\n</section>\n\n<!-- 32 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">32</span><span class=\"track\">Certification Center</span></div>\n  <h2>Flash Cards</h2>\n  <div class=\"flash-wrap\" id=\"flash-wrap6\"></div>\n</section>\n\n<!-- 33 QUIZ -->\n<section class=\"chapter reveal\" id=\"sec-quiz6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">33</span><span class=\"track\">Certification Center</span></div>\n  <h2>Certification Readiness Quiz</h2>\n  <div id=\"quiz-wrap6\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score6\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 34 CERTIFICATE -->\n<section class=\"chapter reveal\" id=\"sec-cert6\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">34</span><span class=\"track\">Certification Center</span></div>\n  <h2>Completion &amp; Certificate Preview</h2>\n  <div class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle6\"><span id=\"badge-pct6\">0%</span></div>\n    <h3 id=\"badge-title6\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub6\">Complete every section and the quiz to preview your certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 6: Security, Encryption, PKI &amp; Vault/KMS</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display6\">0/20</span> \u00b7 Date: <span id=\"cert-date-display6\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Security, Encryption, PKI &amp; Vault/KMS \u2014 Day 6 \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n\n", "js": "\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0, labsDone:new Set() };\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initEncBasics(); initSymmetric(); initAsymmetric(); initSymVsAsym(); initTls6(); initHybrid();\n  initPki(); initCertViz(); initCertValidation();\n  initMek(); initHsmDecision(); initEncStorage();\n  initSecretsDash(); initSecretVersions(); initKeyRotationTimeline(); initAppIntegration(); initKeyReplication(); initAppFailure();\n  initBestPractices(); initNetworkLayers(); initBastion(); initAuditCompliance(); initMistakes();\n  initConsoleSim6(); initTerminal6(); initLabs6(); initTroubleshoot6(); initArchDesign();\n  initFlashcards6(); initQuiz6(); updateBadge6();\n});\nfunction initParticles(){\n  const c=document.getElementById('particles'); const ctx=c.getContext('2d'); let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N=Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){ ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar=document.getElementById('progress-bar'); const heroProgress=document.getElementById('hero-progress');\n  window.addEventListener('scroll', ()=>{\n    const scrollTop=window.scrollY; const docH=document.documentElement.scrollHeight-window.innerHeight;\n    const pct=docH>0?(scrollTop/docH)*100:0;\n    bar.style.width=pct+'%'; if(heroProgress) heroProgress.textContent=Math.round(pct)+'%';\n    window.__lastScrollPct6=pct; updateBadge6(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections=document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect=sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=>a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title=sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML=matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n;\n\n/* ---------- simple reversible cipher for simulation ---------- */\nfunction simpleCipher(str){\n  return str.split('').map(ch=>{\n    const code = ch.charCodeAt(0);\n    return String.fromCharCode(code + 3);\n  }).join('');\n}\nfunction toHexBlocks(str){\n  return str.split('').map(ch=> ch.charCodeAt(0).toString(16).padStart(2,'0')).join(' ');\n}\n\n/* ---------- encryption basics ---------- */\nfunction initEncBasics(){\n  const btn = document.getElementById('enc-run'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const plain = document.getElementById('enc-plaintext').value || 'Hello';\n    document.getElementById('enc-out-plain').textContent = plain;\n    document.getElementById('enc-out-cipher').textContent = '';\n    document.getElementById('enc-out-decrypted').textContent = '';\n    const cipherHex = toHexBlocks(simpleCipher(plain));\n    setTimeout(()=> document.getElementById('enc-out-cipher').textContent = cipherHex, 300);\n    setTimeout(()=> document.getElementById('enc-out-decrypted').textContent = plain, 1000);\n  });\n}\n\n/* ---------- symmetric encryption ---------- */\nfunction initSymmetric(){\n  const btn = document.getElementById('sym-run'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const label = document.getElementById('sym-cipher-label'); const msg = document.getElementById('sym-msg');\n    label.textContent = 'encrypting...';\n    setTimeout(()=>{ label.textContent = 'report.pdf.enc (AES-256)'; msg.textContent = '\u2713 Encrypted with a single shared key \u2014 the same key decrypts it on the receiving end.'; msg.style.color='var(--green)'; }, 600);\n  });\n}\n\n/* ---------- asymmetric encryption ---------- */\nfunction initAsymmetric(){\n  const btn = document.getElementById('asym-run'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const label = document.getElementById('asym-cipher-label'); const msg = document.getElementById('asym-msg');\n    label.textContent = 'encrypting with public key...';\n    setTimeout(()=>{ label.textContent = '8f3a...c91e (ciphertext)'; msg.textContent = '\u2713 Only the matching private key can reverse this \u2014 the public key that created it cannot decrypt its own output.'; msg.style.color='var(--green)'; }, 700);\n  });\n}\n\n/* ---------- symmetric vs asymmetric decision ---------- */\nfunction initSymVsAsym(){\n  const btns = document.querySelectorAll('[data-sa]'); if(!btns.length) return;\n  const result = document.getElementById('sa-result');\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      if(b.dataset.sa==='sym'){ result.style.display='block'; result.style.background='var(--green-dim)'; result.style.color='var(--green)'; result.style.borderColor='rgba(62,194,143,.35)'; result.textContent='\u2713 Correct \u2014 symmetric encryption (AES) is dramatically faster for bulk data. This is exactly what OCI uses for encryption at rest.'; }\n      else { result.style.display='block'; result.style.background='var(--red-dim)'; result.style.color='var(--red-bright)'; result.style.borderColor='rgba(199,70,52,.35)'; result.textContent='\u2717 Asymmetric encryption is far too slow for 4GB of data directly \u2014 it\\'s used to protect a small key, not bulk content.'; }\n    });\n  });\n}\n\n/* ---------- TLS handshake (encryption section) ---------- */\nfunction initTls6(){\n  const wrap = document.getElementById('tls6-flow'); if(!wrap) return;\n  const steps = ['Client Hello','Server sends Certificate (public key)','Client verifies cert chain','Asymmetric key exchange','Symmetric session key derived','AES-encrypted data flows'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('tls6-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    steps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*450));\n  });\n}\n\n/* ---------- hybrid / envelope encryption ---------- */\nfunction initHybrid(){\n  const wrap = document.getElementById('hybrid-flow'); if(!wrap) return;\n  const steps = ['Generate random DEK','Encrypt data with DEK (AES, fast)','Encrypt DEK with MEK (RSA, small)','Store encrypted data + wrapped DEK','Later: MEK unwraps DEK','DEK decrypts the data'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('hybrid-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    steps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*450));\n  });\n}\n\n;\n\n/* ---------- PKI chain ---------- */\nfunction initPki(){\n  const nodes = document.querySelectorAll('#pki-chain .pki-node'); if(!nodes.length) return;\n  const detail = document.getElementById('pki-detail');\n  const info = {\n    root: 'Root CA: the ultimate trust anchor, kept offline for security. Its certificate is self-signed and pre-installed in browsers/OS trust stores.',\n    intermediate: 'Intermediate CA: signed by the Root, used for day-to-day certificate issuance so the Root never has to be brought online.',\n    leaf: 'Leaf Certificate: the actual certificate for your domain, signed by the Intermediate CA \u2014 this is what a browser receives from your server.'\n  };\n  nodes.forEach(n=> n.addEventListener('click', ()=>{ nodes.forEach(x=>x.classList.remove('active')); n.classList.add('active'); detail.textContent = info[n.dataset.pki]; }));\n}\n\n/* ---------- certificate visualizer ---------- */\nfunction initCertViz(){\n  const wrap = document.getElementById('certviz-flow'); if(!wrap) return;\n  const steps = ['Generate key pair','Create CSR (Certificate Signing Request)','Submit CSR to CA','CA validates domain ownership','CA signs certificate','Certificate installed on server'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('certviz-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    const log = document.getElementById('certviz-log'); log.textContent='';\n    const lines = [\n      '$ openssl genrsa -out private.key 2048',\n      '$ openssl req -new -key private.key -out request.csr',\n      'Submitting CSR to CA...',\n      'CA: validating domain ownership via DNS TXT record...',\n      'CA: signing certificate with Intermediate CA key...',\n      '\u2713 certificate.pem issued, valid 90 days'\n    ];\n    steps.forEach((s,i)=> setTimeout(()=>{ els[i].classList.add('lit'); log.textContent += lines[i]+'\\n'; log.scrollTop = log.scrollHeight; }, i*500));\n  });\n}\n\n/* ---------- certificate validation troubleshooting ---------- */\nfunction initCertValidation(){\n  const btns = document.querySelectorAll('#cert-case-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('cert-case-panel');\n  const cases = {\n    expired: {err:'NET::ERR_CERT_DATE_INVALID \u2014 certificate expired on 2026-06-01', fix:'Fix: renew the certificate before expiry, and set up automated renewal (e.g. via ACME/Let\\'s Encrypt or OCI Certificates service) to prevent recurrence.'},\n    revoked: {err:'SEC_ERROR_REVOKED_CERTIFICATE \u2014 the certificate has been revoked by the issuing CA', fix:'Fix: the private key was likely compromised \u2014 issue a brand new certificate with a new key pair; don\\'t just \"un-revoke\".'},\n    selfsigned: {err:'NET::ERR_CERT_AUTHORITY_INVALID \u2014 self-signed certificate', fix:'Fix: fine for internal/dev tools with a manually trusted CA, but for public-facing services, use a certificate from a publicly trusted CA.'},\n    wronghost: {err:'NET::ERR_CERT_COMMON_NAME_INVALID \u2014 certificate is valid for api.example.com, not www.example.com', fix:'Fix: reissue the certificate including all required hostnames as Subject Alternative Names (SANs), or use a wildcard certificate.'}\n  };\n  function render(key){ const c = cases[key]; panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.err}</p><p class=\"small mt-lg\" style=\"color:var(--green);\">\u2713 ${c.fix}</p>`; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.certcase); }));\n  render('expired');\n}\n\n;\n\n/* ---------- HSM decision tree ---------- */\nfunction initHsmDecision(){\n  const btns = document.querySelectorAll('[data-hsmq]'); if(!btns.length) return;\n  const result = document.getElementById('hsmq-result');\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      if(b.dataset.hsmq==='hsm'){ result.style.display='block'; result.style.background='var(--green-dim)'; result.style.color='var(--green)'; result.style.borderColor='rgba(62,194,143,.35)'; result.textContent='\u2713 Correct \u2014 HSM Protected mode uses FIPS 140-2 Level 3 validated hardware, which is exactly what strict compliance audits require proof of.'; }\n      else { result.style.display='block'; result.style.background='var(--red-dim)'; result.style.color='var(--red-bright)'; result.style.borderColor='rgba(199,70,52,.35)'; result.textContent='\u2717 Software Protected keys don\\'t carry FIPS 140-2 Level 3 hardware attestation \u2014 that requires HSM Protected mode.'; }\n    });\n  });\n}\n\n/* ---------- master encryption keys console ---------- */\nfunction initMek(){\n  const btn = document.getElementById('mek-create'); if(!btn) return;\n  let keys = [{name:'prod-mek-01', state:'enabled'}];\n  const list = document.getElementById('mek-list');\n  function render(){\n    list.innerHTML = keys.map((k,i)=>`\n      <div class=\"key-card\"><div class=\"key-card-top\"><strong>${k.name}</strong><span class=\"key-state ${k.state}\">${k.state.replace('-',' ')}</span></div>\n      <div class=\"key-actions\">\n        <button class=\"chip-btn\" data-krotate=\"${i}\">Rotate</button>\n        <button class=\"chip-btn\" data-ktoggle=\"${i}\">${k.state==='enabled'?'Disable':'Enable'}</button>\n        <button class=\"chip-btn\" data-kdelete=\"${i}\">${k.state==='pending-deletion'?'Cancel Deletion':'Schedule Deletion'}</button>\n      </div></div>`).join('');\n    state.labsDone.add('mek-lab');\n  }\n  btn.addEventListener('click', ()=>{\n    const name = document.getElementById('mek-new-name').value.trim() || 'mek-'+(keys.length+1);\n    keys.push({name, state:'enabled'}); document.getElementById('mek-new-name').value=''; render();\n  });\n  list.addEventListener('click', e=>{\n    if(e.target.dataset.krotate!==undefined){ /* rotation creates a new version silently */ }\n    if(e.target.dataset.ktoggle!==undefined){ const i=e.target.dataset.ktoggle; keys[i].state = keys[i].state==='enabled'?'disabled':'enabled'; render(); }\n    if(e.target.dataset.kdelete!==undefined){ const i=e.target.dataset.kdelete; keys[i].state = keys[i].state==='pending-deletion'?'enabled':'pending-deletion'; render(); }\n  });\n  render();\n}\n\n/* ---------- encrypt storage ---------- */\nfunction initEncStorage(){\n  const btn = document.getElementById('encstorage-apply'); if(!btn) return;\n  const labels = { block:'Block Volume \"data-vol-01\"', object:'Object Storage bucket \"app-backups\"', boot:'Boot Volume \"web-vm-01-boot\"', file:'File Storage \"shared-fs\"' };\n  let target = 'block';\n  document.querySelectorAll('[data-est]').forEach(b=> b.addEventListener('click', ()=>{ document.querySelectorAll('[data-est]').forEach(x=>x.classList.remove('active')); b.classList.add('active'); target = b.dataset.est; }));\n  btn.addEventListener('click', ()=>{\n    document.getElementById('encstorage-result').innerHTML = `\u2713 ${labels[target]} re-encrypted with Vault key \"prod-mek-01\". Existing data is re-wrapped with a new Data Encryption Key without downtime.`;\n  });\n}\n\n;\n\n/* ---------- secrets dashboard ---------- */\nfunction initSecretsDash(){\n  const btn = document.getElementById('secret-create'); if(!btn) return;\n  let secrets = [{name:'db-password', type:'Password', version:1}];\n  const list = document.getElementById('secret-list');\n  function render(){\n    list.innerHTML = secrets.map(s=>`<div class=\"version-row current\"><span><strong>${s.name}</strong> \u2014 ${s.type}</span><span class=\"small\">v${s.version}</span></div>`).join('');\n  }\n  btn.addEventListener('click', ()=>{\n    const name = document.getElementById('secret-new-name').value.trim() || 'secret-'+(secrets.length+1);\n    const type = document.getElementById('secret-new-type').value;\n    secrets.push({name, type, version:1}); document.getElementById('secret-new-name').value=''; render();\n  });\n  render();\n}\n\n/* ---------- secret versions & rotation ---------- */\nfunction initSecretVersions(){\n  const btn = document.getElementById('secver-rotate'); if(!btn) return;\n  let versions = [{v:1, state:'deprecated'}, {v:2, state:'previous'}, {v:3, state:'current'}];\n  const list = document.getElementById('secver-list');\n  function render(){\n    list.innerHTML = versions.slice().reverse().map(v=>`<div class=\"version-row ${v.state==='current'?'current':''}\"><span>Version ${v.v}</span><span class=\"small\">${v.state}</span></div>`).join('');\n  }\n  btn.addEventListener('click', ()=>{\n    versions.forEach(v=>{ if(v.state==='current') v.state='previous'; else if(v.state==='previous') v.state='deprecated'; });\n    versions.push({v: versions.length+1, state:'current'});\n    render();\n  });\n  render();\n}\n\n/* ---------- key rotation timeline animation ---------- */\nfunction initKeyRotationTimeline(){\n  const wrap = document.getElementById('rotation-timeline'); if(!wrap) return;\n  const steps = ['Current key version active','Rotation triggered','New key version generated','New version becomes current','Old version kept for decrypting existing data','Old version eventually retired'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"rot-arrow\">\u2192</span>':'')+`<div class=\"rot-step\">${s}</div>`).join('');\n  document.getElementById('rotation-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.rot-step'); els.forEach(e=>e.classList.remove('current'));\n    steps.forEach((s,i)=> setTimeout(()=>{ els.forEach(e=>e.classList.remove('current')); els[i].classList.add('current'); }, i*500));\n  });\n}\n\n/* ---------- application integration ---------- */\nfunction initAppIntegration(){\n  const wrap = document.getElementById('appint-flow'); if(!wrap) return;\n  const steps = ['App starts, no hardcoded secret','App authenticates via Instance Principal','App calls Vault: GetSecretBundle','Vault verifies IAM policy allows it','Secret value returned in memory only','App connects to database using it'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('appint-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    const log = document.getElementById('appint-log'); log.textContent='';\n    steps.forEach((s,i)=> setTimeout(()=>{ els[i].classList.add('lit'); log.textContent += `[app] ${s}\\n`; log.scrollTop=log.scrollHeight; }, i*450));\n  });\n}\n\n/* ---------- key replication & DR ---------- */\nfunction initKeyReplication(){\n  const btn = document.getElementById('dr-failover'); if(!btn) return;\n  const primary = document.getElementById('dr-primary'); const secondary = document.getElementById('dr-secondary');\n  const arrow = document.getElementById('dr-arrow'); const msg = document.getElementById('dr-msg');\n  btn.addEventListener('click', ()=>{\n    primary.classList.add('failed'); arrow.textContent='\u2715';\n    msg.innerHTML = '\ud83d\udd25 Primary region us-ashburn-1 is unreachable. <strong style=\"color:var(--green);\">Failing over to replica in us-phoenix-1</strong> \u2014 applications reconfigured to use the replica Vault, no data loss since keys were already in sync.';\n  });\n  document.getElementById('dr-reset').addEventListener('click', ()=>{\n    primary.classList.remove('failed'); arrow.textContent='\u21c4';\n    msg.textContent = 'Both regions healthy \u2014 keys are replicated and in sync.';\n  });\n}\n\n/* ---------- application failure diagnosis ---------- */\nfunction initAppFailure(){\n  const rotateBtn = document.getElementById('appfail-rotate'); if(!rotateBtn) return;\n  rotateBtn.addEventListener('click', ()=>{\n    document.getElementById('appfail-error').style.display='block';\n    document.getElementById('appfail-opts').style.display='flex';\n    document.getElementById('appfail-check').style.display='inline-flex';\n    rotateBtn.disabled = true;\n  });\n  document.getElementById('appfail-check').addEventListener('click', ()=>{\n    const sel = document.querySelector('input[name=\"appfail\"]:checked');\n    const fb = document.getElementById('appfail-feedback');\n    if(!sel){ fb.textContent='Select a diagnosis first.'; fb.style.color='var(--amber)'; return; }\n    if(sel.value==='right'){ fb.textContent='\u2713 Correct \u2014 rotating the secret in the Vault doesn\\'t automatically update the actual database password or restart apps holding a cached connection. Both sides need to be updated together, ideally via automated rotation.'; fb.style.color='var(--green)'; }\n    else { fb.textContent='\u2717 Not quite \u2014 the Vault and network are fine here; the mismatch is between the new secret value and what the database/app are actually using.'; fb.style.color='var(--red-bright)'; }\n  });\n}\n\n;\n\n/* ---------- best practices checklist ---------- */\nfunction initBestPractices(){\n  const wrap = document.getElementById('bp-list'); if(!wrap) return;\n  const items = [\n    ['Least Privilege','Grant only the exact permissions a principal needs, nothing more.'],\n    ['Zero Trust','Re-verify every request regardless of network location.'],\n    ['Defense in Depth','Layer independent controls \u2014 no single point of failure.'],\n    ['Key Rotation','Rotate encryption keys on a schedule, not just when compromised.'],\n    ['Secret Rotation','Rotate credentials automatically, integrated with the app.'],\n    ['Short-Lived Credentials','Prefer session tokens/instance principals over long-lived API keys.'],\n    ['Compliance Mapping','Know which framework (PCI, HIPAA, etc.) governs each workload.'],\n  ];\n  wrap.innerHTML = items.map(([t,d],i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div><div class=\"lab-title\">${t}</div><div class=\"lab-desc\">${d}</div></div></div>`).join('');\n  wrap.querySelectorAll('.lab-item').forEach(item=> item.addEventListener('click', ()=> item.classList.toggle('done')));\n}\n\n/* ---------- network security layers (reuse castle pattern) ---------- */\nfunction initNetworkLayers(){\n  const wrap = document.getElementById('netlayers'); if(!wrap) return;\n  const layers = ['Security Lists (subnet-wide)','NSGs (per-VNIC)','Bastion (brokered access, no public SSH)','Private Subnets (no direct internet)','Encryption at Rest (Vault-managed keys)','Encryption in Transit (TLS)'];\n  wrap.innerHTML = layers.map((l,i)=>`<div class=\"castle-layer\" data-i=\"${i}\"><span class=\"cl-name\">${l}</span><button class=\"chip-btn\" data-remove6=\"${i}\">Remove</button></div>`).join('');\n  let removed = new Set();\n  function render(){ wrap.querySelectorAll('.castle-layer').forEach((el,i)=> el.classList.toggle('removed', removed.has(i))); }\n  wrap.addEventListener('click', e=>{ if(e.target.dataset.remove6!==undefined){ removed.add(parseInt(e.target.dataset.remove6)); render(); } });\n}\n\n/* ---------- bastion service ---------- */\nfunction initBastion(){\n  const btn = document.getElementById('bastion-create'); if(!btn) return;\n  const wrap = document.getElementById('bastion-flow'); const msg = document.getElementById('bastion-msg');\n  const steps = ['Request session (target: db-vm-01)','Bastion validates IAM policy','Session created, 5-min TTL','SSH tunnel established','Admin connects through tunnel','Session auto-expires'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  btn.addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    steps.forEach((s,i)=> setTimeout(()=>{ els[i].classList.add('lit'); msg.textContent = s; if(i===steps.length-1) msg.textContent = '\u2713 Session complete \u2014 the private instance was never given a public IP or open inbound SSH rule.'; }, i*450));\n  });\n}\n\n/* ---------- audit & compliance ---------- */\nfunction initAuditCompliance(){\n  const wrap = document.getElementById('audit-timeline'); if(!wrap) return;\n  const events = [\n    ['09:12:03', '\ud83d\udd11', 'Key \"prod-mek-01\" rotated by user admin@company.com'],\n    ['09:15:41', '\ud83d\udddd', 'Secret \"db-password\" accessed by instance principal web-vm-01'],\n    ['09:20:07', '\u26a0\ufe0f', 'Failed decrypt attempt \u2014 insufficient IAM policy for user j.doe'],\n    ['09:31:55', '\ud83d\udd12', 'Vault \"prod-vault\" policy updated'],\n  ];\n  wrap.innerHTML = events.map(([t,i,d])=>`<div class=\"audit-item\"><span class=\"audit-time\">${t}</span><span class=\"audit-icon\">${i}</span><span>${d}</span></div>`).join('');\n\n  const cards = document.querySelectorAll('#compliance-grid6 .compliance-card'); if(!cards.length) return;\n  const detail = document.getElementById('compliance6-detail');\n  const info = {\n    pci: 'PCI DSS: mandates strong cryptography and key management for cardholder data \u2014 Vault + KMS directly support this requirement.',\n    hipaa: 'HIPAA: requires encryption and access auditing for patient health information \u2014 Audit + Vault logging satisfy the technical safeguard requirements.',\n    iso: 'ISO 27001: an ISMS standard \u2014 key management and audit logging map to its cryptographic controls (Annex A.10).',\n    soc2: 'SOC 2: audits controls around security, availability, and confidentiality \u2014 Vault access logs are common evidence.',\n    gdpr: 'GDPR: requires appropriate technical measures to protect personal data \u2014 encryption at rest/in transit is explicitly called out as a safeguard.',\n    nist: 'NIST (800-53/CSF): a control framework many public-sector and regulated workloads must map their encryption/key practices to.'\n  };\n  cards.forEach(c=> c.addEventListener('click', ()=> detail.textContent = info[c.dataset.c6]));\n}\n\n/* ---------- common mistakes / attack simulation ---------- */\nfunction initMistakes(){\n  const cards = document.querySelectorAll('#mistake-grid .mistake-card'); if(!cards.length) return;\n  const result = document.getElementById('mistake-result');\n  const info = {\n    hardcoded: 'An attacker who reads your source code (or a leaked repo) instantly has the credential \u2014 no need to breach any infrastructure at all.',\n    shared: 'One compromised laptop or departing employee means every service using that shared key is now exposed, with no way to revoke access for just one person.',\n    norotation: 'A key leaked months ago is still valid today \u2014 the exposure window never closes.',\n    excessive: 'A single compromised low-privilege service account can pivot to \"manage all-resources,\" turning a minor breach into a full tenancy compromise.',\n    publicbucket: 'Any anonymous internet user can list and download every object \u2014 this is one of the most common real-world cloud data breach causes.',\n    noaudit: 'Without audit logs, you often can\\'t tell what was accessed, when, or by whom \u2014 incident response becomes guesswork.'\n  };\n  cards.forEach(c=> c.addEventListener('click', ()=>{ result.style.display='block'; result.textContent = '\ud83d\udca5 ' + info[c.dataset.m]; }));\n}\n\n;\n\n/* ---------- console simulator 6 ---------- */\nfunction initConsoleSim6(){\n  const nav = document.querySelectorAll('.console-nav div[data-panel6]'); if(!nav.length) return;\n  nav.forEach(item=>{\n    item.addEventListener('click', ()=>{\n      nav.forEach(n=>n.classList.remove('active')); item.classList.add('active');\n      document.querySelectorAll('.console-panel6').forEach(p=>p.style.display='none');\n      document.getElementById('panel6-'+item.dataset.panel6).style.display='';\n    });\n  });\n}\n\n/* ---------- CLI terminal 6 ---------- */\nfunction initTerminal6(){\n  const out = document.getElementById('term-out6'); const input = document.getElementById('term-input6'); if(!input) return;\n  const responses = {\n    'help': `Available commands:\n  oci kms management vault create\n  oci kms management key create\n  oci kms management key list\n  oci vault secret create\n  oci vault secret list\n  oci vault secret update\n  oci kms management key schedule-deletion\n  oci kms management key cancel-deletion\n  clear`,\n    'oci kms management vault create': `{ \"data\": {\"display-name\": \"prod-vault\", \"vault-type\": \"VIRTUAL_PRIVATE\", \"lifecycle-state\": \"ACTIVE\"} }`,\n    'oci kms management key create': `{ \"data\": {\"display-name\": \"prod-mek-01\", \"protection-mode\": \"HSM\", \"lifecycle-state\": \"ENABLED\"} }`,\n    'oci kms management key list': `{ \"data\": [{\"display-name\": \"prod-mek-01\", \"lifecycle-state\": \"ENABLED\"}] }`,\n    'oci vault secret create': `{ \"data\": {\"secret-name\": \"db-password\", \"lifecycle-state\": \"ACTIVE\"} }`,\n    'oci vault secret list': `{ \"data\": [{\"secret-name\": \"db-password\", \"current-version-number\": 3}] }`,\n    'oci vault secret update': `{ \"data\": {\"secret-name\": \"db-password\", \"current-version-number\": 4} }`,\n    'oci kms management key schedule-deletion': `{ \"data\": {\"lifecycle-state\": \"PENDING_DELETION\", \"time-of-deletion\": \"2026-08-23T00:00:00Z\"} }`,\n    'oci kms management key cancel-deletion': `{ \"data\": {\"lifecycle-state\": \"ENABLED\"} }`\n  };\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  function print(cmd, text, isErr){\n    const line = document.createElement('div');\n    line.innerHTML = `<div class=\"cmdline\">${esc(cmd)}</div><div style=\"color:${isErr?'#ff8a7a':'#c9f7d8'}; margin:4px 0 12px; white-space:pre-wrap;\">${esc(text)}</div>`;\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n  }\n  print('help', 'Welcome to the OCI CLI simulator. Type \"help\" for the supported command list.');\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const cmd = input.value.trim(); input.value=''; if(!cmd) return;\n    if(cmd==='clear'){ out.innerHTML=''; return; }\n    if(responses[cmd]){ print(cmd, responses[cmd]); return; }\n    print(cmd, 'Command not recognized in this simulator. Type \"help\" for the supported list.', true);\n  });\n}\n\n/* ---------- hands-on labs checklist ---------- */\nfunction initLabs6(){\n  const wrap = document.getElementById('labs6-list'); if(!wrap) return;\n  const labs = [\n    ['Create Vault','Understand Vault types from the Vault & KMS Architecture section.'],\n    ['Create Master Encryption Key','Use the Master Encryption Keys console to create a key.'],\n    ['Create Secret','Use the Secrets Dashboard to create a secret.'],\n    ['Encrypt Block Volume','Assign a Vault key to a Block Volume.'],\n    ['Encrypt Object Storage','Assign a Vault key to an Object Storage bucket.'],\n    ['Rotate Key','Rotate a key in the Master Encryption Keys console.'],\n    ['Retrieve Secret','Run the Application Integration simulation.'],\n    ['Replicate Key','Review the Key Replication & DR failover simulation.'],\n    ['Audit Secret Access','Review the Audit event timeline.'],\n  ];\n  wrap.innerHTML = labs.map(([t,d],i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div><div class=\"lab-title\">Lab ${i+1}: ${t}</div><div class=\"lab-desc\">${d}</div></div></div>`).join('');\n  function updateProgress(){ document.getElementById('labs6-progress').textContent = `${wrap.querySelectorAll('.lab-item.done').length} / ${labs.length} labs complete`; }\n  wrap.querySelectorAll('.lab-item').forEach(item=> item.addEventListener('click', ()=>{ item.classList.toggle('done'); updateProgress(); updateBadge6(); }));\n  updateProgress();\n}\n\n/* ---------- troubleshooting lab 6 ---------- */\nfunction initTroubleshoot6(){\n  const btns = document.querySelectorAll('#ts6-case-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('ts6-panel');\n  const cases = {\n    accessdenied: {err:'ServiceError: NotAuthorizedOrNotFound accessing secret \"db-password\"', hint:'Check the IAM policy for \"use secret-family\" or \"manage secret-family\" on the calling principal.', fix:'Fix: grant the calling principal (user, group, or dynamic group) the correct verb on secret-family in the right compartment.'},\n    expiredsecret: {err:'Application error: secret bundle stage \"CURRENT\" not found or expired', hint:'Check whether the secret version was deleted or deprecated without the app being updated.', fix:'Fix: update the application to fetch the current version, or restore/recreate the needed secret version.'},\n    wrongpolicy: {err:'ServiceError: Authorization failed for kms decrypt operation', hint:'Compare the policy verb against what Vault/KMS operations actually need \u2014 decrypt requires \"use\" at minimum.', fix:'Fix: update the policy to grant \"use key-delegate\" (or appropriate verb) on the specific key OCID or key-family.'},\n    keydisabled: {err:'ServiceError: Key is disabled and cannot be used for cryptographic operations', hint:'Check the key\\'s lifecycle state in the Master Encryption Keys console.', fix:'Fix: re-enable the key if the disablement was unintentional; disabled keys block all encrypt/decrypt operations using it.'},\n    scheduleddeletion: {err:'ServiceError: Key is pending deletion and cannot be used', hint:'A key scheduled for deletion is still enabled but marked for future removal.', fix:'Fix: cancel the scheduled deletion if this was a mistake \u2014 there\\'s a mandatory waiting window specifically for this.'},\n    replicationdelay: {err:'Data encrypted in the primary region can\\'t yet be decrypted via the replica.', hint:'Replication is asynchronous \u2014 there can be a brief propagation delay.', fix:'Fix: wait for replication to catch up, or design failover procedures to account for a small RPO (recovery point objective) gap.'},\n    appauthfail: {err:'Application cannot authenticate to Vault: \"no credential found\"', hint:'Check whether the app is using an instance principal / dynamic group correctly.', fix:'Fix: verify the dynamic group\\'s matching rule includes this instance, and that a policy grants it access to the Vault.'}\n  };\n  function render(key){\n    const c = cases[key];\n    panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.err}</p>\n      <button class=\"chip-btn active mt-lg\" id=\"ts6-hint-btn\">Show hint</button>\n      <p class=\"small mt-lg\" id=\"ts6-hint\" style=\"display:none;\">${c.hint}</p>\n      <button class=\"chip-btn mt-lg\" id=\"ts6-fix-btn\" style=\"display:none;\">Reveal fix</button>\n      <p class=\"small mt-lg\" id=\"ts6-fix\" style=\"display:none; color:var(--green);\">${c.fix}</p>`;\n    document.getElementById('ts6-hint-btn').addEventListener('click', function(){ document.getElementById('ts6-hint').style.display='block'; document.getElementById('ts6-fix-btn').style.display='inline-flex'; this.disabled=true; });\n    document.getElementById('ts6-fix-btn').addEventListener('click', function(){ document.getElementById('ts6-fix').style.display='block'; this.disabled=true; });\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.case6); }));\n  render('accessdenied');\n}\n\n/* ---------- security architecture design exercise ---------- */\nfunction initArchDesign(){\n  const btn = document.getElementById('design-evaluate'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    let score = 0; let notes = [];\n    if(document.getElementById('design-vault').value==='vpv'){ score+=20; notes.push('\u2713 Virtual Private Vault adds isolation appropriate for healthcare data.'); } else notes.push('\u26a0 A Shared Vault is acceptable but offers less isolation than a VPV.');\n    if(document.getElementById('design-keyprotect').value==='hsm'){ score+=20; notes.push('\u2713 HSM Protected keys satisfy strict compliance hardware requirements.'); } else notes.push('\u2717 Software Protected keys likely won\\'t satisfy HIPAA/PCI hardware-backed key requirements.');\n    if(document.getElementById('design-bastion').value==='bastion'){ score+=20; notes.push('\u2713 Bastion avoids exposing private instances directly to the internet.'); } else notes.push('\u2717 Direct public SSH exposes instances unnecessarily \u2014 use Bastion instead.');\n    if(document.getElementById('design-netsec').value==='both'){ score+=20; notes.push('\u2713 Security Lists + NSGs together give defense-in-depth at the network layer.'); } else notes.push('\u26a0 Security Lists alone work, but NSGs add finer-grained, defense-in-depth control.');\n    if(document.getElementById('design-iam').value==='least'){ score+=20; notes.push('\u2713 Least-privilege IAM policies limit blast radius if a credential is compromised.'); } else notes.push('\u2717 Broad \"manage all-resources\" policies violate least privilege and are a common audit finding.');\n    document.getElementById('design-ring').style.setProperty('--dscore', score);\n    document.getElementById('design-score-val').textContent = score;\n    document.getElementById('design-feedback').innerHTML = notes.join('<br>');\n  });\n}\n\n;\n\n/* ---------- flashcards 6 ---------- */\nfunction initFlashcards6(){\n  const wrap = document.getElementById('flash-wrap6'); if(!wrap) return;\n  const cards = [\n    ['Symmetric encryption','One shared key encrypts and decrypts \u2014 fast, hard to distribute'],\n    ['Asymmetric encryption','Public/private key pair \u2014 slower, easy key distribution'],\n    ['Envelope encryption','MEK wraps a DEK; the DEK encrypts the actual data'],\n    ['Root CA','Self-signed, offline trust anchor at the top of a PKI chain'],\n    ['Chain of trust','Root CA signs Intermediate CA, which signs your leaf certificate'],\n    ['HSM Protected','FIPS 140-2 Level 3 hardware-backed key storage'],\n    ['Scheduled key deletion','Mandatory 7-30 day wait before permanent deletion'],\n    ['Secret version','A new version is created on rotation; old ones can persist briefly'],\n    ['Cross-region replication','Keeps a Vault usable if the primary region fails'],\n    ['Bastion','Brokered, TTL-limited SSH access \u2014 no permanent public exposure'],\n    ['Least privilege','Grant only the exact permissions needed, nothing more'],\n    ['Envelope vs direct encryption','OCI Vault never encrypts your data directly with the MEK'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- certification quiz 6 ---------- */\nfunction initQuiz6(){\n  const wrap = document.getElementById('quiz-wrap6'); if(!wrap) return;\n  const Q = [\n    {q:'Which encryption type uses a single shared key for both encryption and decryption?', o:['Asymmetric','Symmetric','Hashing','Digital signature'], c:1, e:'Symmetric encryption (like AES) uses one key for both directions.'},\n    {q:'What is the main advantage of asymmetric encryption over symmetric?', o:['It is faster for bulk data','The public key can be shared openly without a secure channel','It uses smaller keys','It requires no math'], c:1, e:'Asymmetric encryption solves the key distribution problem \u2014 the public key needs no secrecy.'},\n    {q:'In OCI Vault, what does the Master Encryption Key (MEK) actually encrypt?', o:['Your data directly','A Data Encryption Key (DEK), which then encrypts your data','Nothing, it only signs', 'The TLS certificate'], c:1, e:'This is envelope encryption \u2014 the MEK wraps a DEK; the DEK does the bulk encryption.'},\n    {q:'A browser shows \"certificate not trusted\" even though the leaf certificate is valid and unexpired. Most likely cause?', o:['The Root CA changed algorithms','A missing Intermediate CA certificate in the server config','The private key expired','DNS is misconfigured'], c:1, e:'Browsers verify the full chain; a missing intermediate cert breaks the trust path even with a valid leaf.'},\n    {q:'Which key protection mode provides FIPS 140-2 Level 3 hardware-backed security?', o:['Software Protected','HSM Protected','Virtual Private Vault only','None of these'], c:1, e:'HSM Protected mode uses validated tamper-resistant hardware.'},\n    {q:'Scheduling a key for deletion in OCI Vault results in:', o:['Immediate permanent deletion','A mandatory 7-30 day waiting period before permanent deletion','The key being disabled forever','No effect until manually confirmed twice'], c:1, e:'The waiting period exists specifically to allow cancellation of accidental deletions.'},\n    {q:'What happens to old key/secret versions immediately after rotation?', o:['They are deleted instantly','They can remain valid briefly so in-flight processes don\\'t break','They become the new current version','Rotation is not possible in OCI'], c:1, e:'Old versions typically persist so data encrypted or authenticated with them can still be handled during the transition.'},\n    {q:'An app was working fine, but after a secret rotation it throws authentication errors. Most likely cause?', o:['The Vault service is down','The actual credential (e.g. DB password) wasn\\'t updated to match the new secret version','The network route changed','TLS certificates expired'], c:1, e:'Rotating the secret record doesn\\'t automatically change the real system\\'s credential unless that\\'s automated together.'},\n    {q:'What is the purpose of OCI Bastion?', o:['To permanently expose a public IP on private instances','To provide short-lived, brokered SSH access to private instances','To replace Security Lists entirely','To store secrets'], c:1, e:'Bastion provides temporary, policy-controlled access without giving the target instance a public IP.'},\n    {q:'Cross-region Vault replication primarily protects against:', o:['Slow application performance','An entire region becoming unavailable','Weak passwords','Expired certificates'], c:1, e:'Replication ensures keys remain usable if the primary region fails, supporting disaster recovery.'},\n    {q:'Which of these is a Data Encryption Key (DEK) used for?', o:['Signing certificates','Bulk encrypting actual data, itself wrapped by the MEK','Authenticating users','Establishing network routes'], c:1, e:'The DEK does the heavy lifting of encrypting your actual data, and is itself protected by the MEK.'},\n    {q:'A digital signature is created by signing with:', o:['The signer\\'s public key','The signer\\'s private key','A shared symmetric key','The recipient\\'s public key'], c:1, e:'Signing uses the private key; anyone can verify using the corresponding public key.'},\n    {q:'Which compliance framework specifically governs cardholder payment data?', o:['HIPAA','GDPR','PCI DSS','ISO 9001'], c:2, e:'PCI DSS specifically applies to organizations handling payment card data.'},\n    {q:'What is the single biggest risk of hardcoding a secret in source code?', o:['Slower performance','Anyone who reads the code (or a leaked repo) has the credential without breaching any infrastructure', 'It uses more disk space', 'It breaks the build'], c:1, e:'Hardcoded secrets bypass all access control the moment the code is read or leaked.'},\n    {q:'Why is \"no key rotation\" a security risk even if a key was never known to be compromised?', o:['It slows down encryption','A leaked key from months ago remains valid indefinitely, keeping the exposure window open', 'It has no real risk', 'Rotation is only cosmetic'], c:1, e:'Without rotation, an undetected past compromise remains exploitable indefinitely.'},\n    {q:'A public Object Storage bucket is a common real-world breach cause because:', o:['It slows down uploads','Any anonymous internet user can list and download every object in it', 'It costs more money', 'It disables encryption at rest'], c:1, e:'Public buckets bypass authentication entirely for anyone who finds the URL.'},\n    {q:'What does \"least privilege\" mean in IAM policy design?', o:['Granting broad access to speed up development','Granting only the exact permissions a principal needs, nothing more', 'Removing all permissions by default forever', 'Only applies to root users'], c:1, e:'Least privilege limits the blast radius if any single credential is compromised.'},\n    {q:'Which is TRUE about encryption at rest in OCI?', o:['It must be manually enabled on every resource','OCI encrypts storage at rest by default using AES-256, even without a customer-managed key', 'Only Block Volumes are encrypted by default', 'It requires a paid add-on'], c:1, e:'OCI encrypts at rest by default; bringing your own Vault key is optional, for extra control.'},\n    {q:'In a TLS handshake, which type of cryptography establishes the initial trust and exchanges the session key?', o:['Symmetric only','Asymmetric (certificate-based)','Hashing only','No cryptography is used at this stage'], c:1, e:'Asymmetric crypto (via the certificate) authenticates the server and helps establish the shared session key; symmetric crypto then encrypts the actual traffic.'},\n    {q:'A key is \"Scheduled for Deletion\" but a team still needs it. What should they do?', o:['Wait for it to be deleted, then recreate manually with the same OCID','Cancel the scheduled deletion before the waiting period ends', 'Immediately export the key material', 'Nothing can be done'], c:1, e:'Cancelling the scheduled deletion restores the key to enabled \u2014 this is exactly why the waiting period exists.'},\n  ];\n  state.quizTotal = Q.length;\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz6-${qi}\">\n      <div class=\"qtext\">${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q6-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n      state.quizAnswered++; if(chosen===Q[qi].c) state.quizScore++;\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score6').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display6').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge6();\n    });\n  });\n}\n\n/* ---------- badge / certificate 6 ---------- */\nfunction updateBadge6(){\n  const scrollPct = window.__lastScrollPct6 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle6'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct6').textContent = combined+'%';\n  const title = document.getElementById('badge-title6'); const sub = document.getElementById('badge-sub6');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Day 6 Complete'; sub.textContent='Certificate preview unlocked below.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the quiz.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the quiz to preview your certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display6').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n}\n"};
